// src/checkout/coupon.ts
export function applyCoupon(price: number, coupon: Coupon, today: string): number {
  if (today > coupon.expiresOn) return price;
  if (price <= MIN_PRICE) return price;                     // MIN_PRICE = 10_000
  const discount = coupon.kind === "percent" ? Math.floor((price * coupon.value) / 100) : coupon.value;
  return Math.max(price - discount, MIN_PRICE);
}

// src/checkout/coupon.test.ts
const c = (kind: "percent" | "fixed", value: number, expiresOn = "2026-12-31") => ({ kind, value, expiresOn });
test("percent coupon", () => expect(applyCoupon(200000, c("percent", 10), "2026-10-26")).toBe(180000));
test("fixed coupon", () => expect(applyCoupon(199000, c("fixed", 20000), "2026-10-26")).toBe(179000));
test("expired coupon", () => expect(applyCoupon(199000, c("fixed", 20000, "2026-10-01"), "2026-10-26")).toBe(199000));
test("cheap course", () => expect(applyCoupon(5000, c("percent", 50), "2026-10-26")).toBe(5000));

